## How It Works

### 1. App Stack Creates Cognito User Pool

The `CognitoConstruct` creates the authentication layer:

// who-knows-aws-services/lib/constructs/CognitoConstruct.ts
export class CognitoConstruct extends Construct {
  public readonly userPool: UserPool
  public readonly userPoolClient: UserPoolClient

  constructor(scope: Construct, id: string, props: CognitoConstructProps) {
    // Create User Pool with email + OTP auth
    this.userPool = new UserPool(this, 'UserPool', {
      signInAliases: { email: true },
      signInPolicy: {
        allowedFirstAuthFactors: { password: true, emailOtp: true },
      },
      // ... password policy, deletion protection, etc.
    })

    // Create user groups: ADMIN, CREATOR, VIEWER
    new CfnUserPoolGroup(this, 'AdminGroup', {
      groupName: 'ADMIN',
      precedence: 0,
    })
    new CfnUserPoolGroup(this, 'CreatorGroup', {
      groupName: 'CREATOR',
      precedence: 1,
    })
    new CfnUserPoolGroup(this, 'ViewerGroup', {
      groupName: 'VIEWER',
      precedence: 2,
    })

    // Lambda triggers for custom messages and post-confirmation
    this.userPool.addTrigger(UserPoolOperation.CUSTOM_MESSAGE, customMessageFn)
    this.userPool.addTrigger(
      UserPoolOperation.POST_CONFIRMATION,
      postConfirmationFn,
    )

    // Export to SSM for mobile clients
    new StringParameter(this, 'UserPoolIdParam', {
      parameterName: `/${project}/${environment}/cognito/user-pool-id`,
      stringValue: this.userPool.userPoolId,
    })
  }
}

### 2. App Stack Creates AppSync API

The `AppSyncConstruct` creates the GraphQL API with the local Cognito User Pool:

// who-knows-aws-services/lib/constructs/AppSyncConstruct.ts
export class AppSyncConstruct extends Construct {
  public readonly api: GraphqlApi

  constructor(scope: Construct, id: string, props: AppSyncConstructProps) {
    const { userPool, schemaPath, environment } = props

    this.api = new GraphqlApi(this, 'Api', {
      name: `sayso-graphql-${environment}`,
      definition: Definition.fromSchema(SchemaFile.fromAsset(schemaPath)),
      authorizationConfig: {
        defaultAuthorization: {
          authorizationType: AuthorizationType.USER_POOL,
          userPoolConfig: { userPool },
        },
        additionalAuthorizationModes: [
          { authorizationType: AuthorizationType.IAM },
          { authorizationType: AuthorizationType.API_KEY, ... },
        ],
      },
    })

    // Export to SSM for mobile clients
    new StringParameter(this, 'ApiIdParam', {
      parameterName: `/${project}/${environment}/appsync/api-id`,
      stringValue: this.api.apiId,
    })
  }
}

